package ai.motionwall.cars;

import android.media.MediaPlayer;
import android.content.SharedPreferences;
import android.os.Handler;
import android.os.Looper;
import android.service.wallpaper.WallpaperService;
import android.view.SurfaceHolder;
import java.io.File;

/**
 * Real MP4 wallpaper — hardware-decoded by Android's video stack, never
 * generated by CPU canvas redraws and never dependent on a network connection.
 * AI generation is an independent, not-yet-implemented future input source.
 */
public final class MotionVideoWallpaperService extends WallpaperService {
    @Override public Engine onCreateEngine() {return new VideoEngine();}

    private final class VideoEngine extends Engine {
        private final Handler handler=new Handler(Looper.getMainLooper());
        private final SharedPreferences prefs=getSharedPreferences(PhotoStore.PREFS,MODE_PRIVATE);
        private final SharedPreferences.OnSharedPreferenceChangeListener listener=(preferences,key)->{
            if(VideoClipStore.VIDEO_KEY.equals(key)) {
                handler.post(()->{
                    if(destroyed)return;
                    // A new locally selected MP4 changes the active wallpaper
                    // without clearing data or reinstalling a new service.
                    closePlayer();
                    startIfVisible();
                });
            }
        };
        private MediaPlayer player;
        private boolean visible, surfaceReady, destroyed;
        private int session;

        @Override public void onCreate(SurfaceHolder holder) {
            super.onCreate(holder);
            prefs.registerOnSharedPreferenceChangeListener(listener);
        }
        @Override public void onSurfaceCreated(SurfaceHolder holder) {
            super.onSurfaceCreated(holder);
            surfaceReady=true;
            startIfVisible();
        }
        @Override public void onVisibilityChanged(boolean isVisible) {
            visible=isVisible;
            if(!visible) {
                if(player!=null)try{if(player.isPlaying())player.pause();}catch(IllegalStateException ignored){}
            } else startIfVisible();
        }
        @Override public void onSurfaceDestroyed(SurfaceHolder holder) {
            surfaceReady=false;
            closePlayer();
            super.onSurfaceDestroyed(holder);
        }
        private void startIfVisible() {
            if(destroyed||!surfaceReady||!visible)return;
            if(player!=null) {
                try{if(!player.isPlaying())player.start();}catch(IllegalStateException ignored){}
                return;
            }
            File file=VideoClipStore.get(MotionVideoWallpaperService.this);
            if(file==null)return;
            final int generation=++session;
            MediaPlayer fresh=new MediaPlayer();
            player=fresh;
            try {
                fresh.setDataSource(file.getAbsolutePath());
                fresh.setDisplay(getSurfaceHolder());
                fresh.setLooping(true);
                fresh.setVolume(0f,0f);
                fresh.setOnPreparedListener(p->{
                    if(generation!=session||destroyed||!surfaceReady)return;
                    try{p.setVideoScalingMode(MediaPlayer.VIDEO_SCALING_MODE_SCALE_TO_FIT);}catch(IllegalStateException ignored){}
                    if(visible)try{p.start();}catch(IllegalStateException ignored){}
                });
                fresh.setOnErrorListener((p,what,extra)->{
                    handler.post(()->{
                        if(generation==session)closePlayer();
                    });
                    return true;
                });
                fresh.prepareAsync();
            }catch(Exception e){closePlayer();}
        }
        private void closePlayer() {
            ++session;
            MediaPlayer old=player;player=null;
            if(old!=null) {
                old.setOnPreparedListener(null);
                old.setOnErrorListener(null);
                try{old.reset();}catch(Exception ignored){}
                try{old.release();}catch(Exception ignored){}
            }
        }
        @Override public void onDestroy() {
            destroyed=true;
            closePlayer();
            handler.removeCallbacksAndMessages(null);
            prefs.unregisterOnSharedPreferenceChangeListener(listener);
            super.onDestroy();
        }
    }
}
